def pair_value(v1, v2):
    """Determine output value from a pair of values at the same column"""
    # Count value occurrences
    counts = {}
    for v in [v1, v2]:
        counts[v] = counts.get(v, 0) + 1

    # If one value appears twice (both same), return 8
    if v1 == v2:
        return 8

    # For different values, use the more frequent one
    if counts[v1] == counts[v2]:
        # Equal counts - special rule needed
        if v1 == 9:
            return 9
        elif v1 == 8 and v2 == 9:
            # [8,9] -> should be 9 (9 is the "upper" value)
            return 9
        elif v1 == 9 and v2 == 8:
            return 9
        else:
            return max(v1, v2)  # fallback
    else:
        # Different counts - return the one that appears more
        if counts[v1] > counts[v2]:
            return v1
        else:
            return v2

